import{_ as t,c as a,al as o,o as i}from"./chunks/framework.D3pXwl8O.js";const d=JSON.parse('{"title":"测试 MC_02-完全自主","description":"","frontmatter":{},"headers":[],"relativePath":"zh/test_cards/mc_02_full_autonomous.md","filePath":"zh/test_cards/mc_02_full_autonomous.md"}'),r={name:"zh/test_cards/mc_02_full_autonomous.md"};function n(s,e,l,p,h,u){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="测试-mc-02-完全自主" tabindex="-1">测试 MC_02-完全自主 <a class="header-anchor" href="#测试-mc-02-完全自主" aria-label="Permalink to &quot;测试 MC_02-完全自主&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>To test the auto modes such as Mission, RTL, etc...</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Plan a mission on the ground. Ensure the mission has</p><ul><li>Takeoff as first waypoint</li><li>Changes in Altitude throughout the mission</li><li>Last waypoint is an RTL</li><li>Duration of 5 to 6 minutes</li></ul><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ Mission</p><p>    ❏ Auto take-off</p><p>    ❏ Changes in Altitude throughout the mission</p><p>    ❏ First waypoint set to Takeoff</p><p>    ❏ Enable Mission End RTL</p><p>    ❏ Duration of 5 to 6 minutes</p><p>    ❏ Auto Disarm on land</p><p>❏ Mission + Manual arm</p><p>    ❏ Arm in any manual mode</p><p>    ❏ Engage Auto (Mission Mode) to trigger take-off</p><p>    ❏ Observe tracking, cornering and proper RTL performance</p><p>    ❏ Upon touching ground, copter should disarm automatically within 2 seconds (disarm time set by parameter: <a href="./../advanced_config/parameter_reference.html#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><p>❏ RTL</p><p>    ❏ Arm and takeoff in position mode</p><p>    ❏ Fly out ~10m from start point</p><p>    ❏ Engage RTL Mode</p><p>    ❏ Observe tracking, cornering and proper RTL performance</p><h2 id="预期成果" tabindex="-1">预期成果 <a class="header-anchor" href="#预期成果" aria-label="Permalink to &quot;预期成果&quot;">​</a></h2><ul><li>当油门升高时，起飞应该是平稳的</li><li>任务应该在第一次尝试时上传</li><li>使用 Auto 时飞机应自动起飞</li><li>Vehicle shoud adjust height to RTL altitude before returning home</li><li>着陆时，直升机不应在地面上反弹</li></ul>',26)]))}const m=t(r,[["render",n]]);export{d as __pageData,m as default};
